        long lastModified = getFileForLastModifiedCheck().lastModified();
        if (lastModified == 0L) {
            throw new FileNotFoundException(getDescription() +
                                                    " cannot be resolved in the file system for resolving its last-modified timestamp");
        }
        return lastModified;
    }

